function prefixesDivBy5(nums) {
  // Build each prefix as an exact BigInt and test it directly.
  const result = [];
  let value = 0n;
  for (let i = 0; i < nums.length; i++) {
    value = value * 2n + BigInt(nums[i]);
    result.push(value % 5n === 0n);
  }
  return result;
}

