function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 14);
  // Vary the share of ones, including all zeros and all ones.
  const oneRate = [0, 0.2, 0.5, 0.8, 1][Math.floor(rand() * 5)];
  return [Array.from({ length: n }, () => (rand() < oneRate ? 1 : 0))];
}
